import { svg, px, writeHeader } from './lib.mjs';

// One independent erase cover per terminal row: CSS hides it after its character pass.
const rows=[];
rows.push({y:43,text:'+--- README.NFO / THE HEADER ARCHIVE ------------------------------------+',scale:1.7,color:'#55ffff'});
rows.push({y:88,text:'README.NFO',scale:8,color:'#ffff55',x:126});
rows.push({y:164,text:'[ 153 STYLES ]  [ 13 FAMILIES ]  [ TEXT + SVG ]',scale:2.5,color:'#ffffff',x:126});
rows.push({y:207,text:'BRING SOME CHARACTER TO YOUR NEXT REPOSITORY.',scale:2.2,color:'#55ffff',x:126});
rows.push({y:248,text:'COPY THE HEADER. MAKE IT YOURS. MIT LICENSE.',scale:2.2,color:'#aaaaaa',x:126});
rows.push({y:292,text:'[DOWNLOAD COMPLETE]   2400 BAUD   20 CANDIDATES',scale:1.8,color:'#55ff55',x:126});
let contents='';
for(const [i,row] of rows.entries()) {
 const x=row.x??52,w=Math.min(850-x,(row.text.length*6)*row.scale),h=row.scale*7;
 contents+=px(row.text,x,row.y,row.scale,row.color);
 contents+=`<g transform="translate(${x} ${row.y-2})"><rect class="cover" width="${w+8}" height="${h+6}" fill="#000" style="--end:${w+8}px;animation-delay:${i*.8}s"/><rect class="cursor" width="${row.scale*5}" height="${h+3}" fill="#fff" style="--end:${w+8}px;animation-delay:${i*.8}s"/></g>`;
}
const sprite=(color,dx=0)=>`<g transform="translate(${790+dx} 272)" fill="${color}"><path d="M0 0h20v4H0zM-4 4h28v16H-4zM0 20h20v4H0zM0 24h4v8H0zM16 24h4v8h-4z"/><rect x="2" y="8" width="4" height="4" fill="#000"/><rect x="14" y="8" width="4" height="4" fill="#000"/><path d="M4 16h12" stroke="#000" stroke-width="3"/></g>`;
const image=svg({height:340,background:'#000000',
css:'.cover{opacity:0;transform:translateX(var(--end));animation:draw .8s steps(72) both}.cursor{opacity:0;animation:cursorpass .8s steps(72) both}.sprite{animation:walk 1.2s steps(2) infinite}.blink{animation:blink 1.4s steps(1) infinite}@keyframes draw{0%{opacity:1;transform:translateX(0)}94%{opacity:1;transform:translateX(var(--end))}95%,100%{opacity:0;transform:translateX(var(--end))}}@keyframes cursorpass{0%{opacity:1;transform:translateX(0)}94%{opacity:1;transform:translateX(var(--end))}95%,100%{opacity:0;transform:translateX(var(--end))}}@keyframes walk{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}@keyframes blink{0%,60%{opacity:1}61%,100%{opacity:0}}@media(prefers-reduced-motion:reduce){.cover,.cursor{display:none}}',
description:'A colourful ANSI header draws itself once at modem speed into README.NFO, 153 styles, thirteen families and a download-complete prompt. A small original block robot keeps bobbing after the reveal.',
body:`<path d="M27 25H933V315H27Z" fill="none" stroke="#0000aa" stroke-width="3"/>
<path d="M34 32H926V308H34Z" fill="none" stroke="#5555ff"/>
${contents}<g class="sprite">${sprite('#ff55ff')}</g><rect x="635" y="292" width="8" height="12" fill="#55ff55" class="blink"/>`
});
const markdown=`<p align="center"><img src="assets/15-ansi-04.svg" width="100%" alt="A bright yellow README.NFO logo and cyan ANSI text draw in at modem speed, with a small magenta robot."></p>

\`\`\`text
README.NFO / THE HEADER ARCHIVE
153 styles / 13 families / text + SVG
Bring some character to your next repository.
Copy the header. Make it yours. MIT license.
[DOWNLOAD COMPLETE]  2400 BAUD  20 CANDIDATES
\`\`\`

[Style catalogue](../../styles/INDEX.md) · [Example galleries](../README.md) · [MIT licence](../../LICENSE)`;
writeHeader(15,{image,markdown,summary:'Bright ANSI letters paint in row by row at modem speed, then a little block robot keeps the connection alive.'});

ansi-05.source:
import {svg,px,writeHeader} from './lib.mjs';

const colours=['#e6fc66','#96ee69','#59e7ba','#76ebee','#e7f6ef'];
let logo='';
for(const [i,letter] of [...'README.NFO'].entries()) logo+=px(letter,54+i*42,55,7,colours[Math.floor(i/2)]);
const rows=[['01','STYLES/','153','STYLE CATALOGUE'],['02','EXAMPLES/','13','VISUAL FAMILIES'],['03','TOOLS/','SVG','PREVIEW + VALIDATE'],['04','LICENSE','MIT','COPY / CUSTOMISE / SHARE']];
let table='';
for(const [i,row] of rows.entries()){
 const y=192+i*34;
 if(i===0)table+=`<rect x="43" y="${y-7}" width="864" height="29" fill="#102c33"/>`;
 table+=px(row[0],58,y,2,'#969eb4')+px(row[1],137,y,2,'#78eae7')+px(row[2],414,y,2,'#bfe991')+px(row[3],516,y,2,'#e4e8ee');
}
const image=svg({height:410,background:'#0a0c11',title:'README.NFO — bulletin board file area',
 description:'A cyan-and-green bulletin-board directory screen. The README.NFO logo and repository stats sit over a ruled file-area table, coloured inverse hotkeys, and a command prompt.',
 body:`<g shape-rendering="crispEdges"><path d="M24 21H936V389H24Z" fill="none" stroke="#4f5468" stroke-width="2"/>
  <path d="M32 29H928V122H32Z" fill="#10151e"/>
  ${px('THE RETRO HEADER ARCHIVE',54,33,2,'#879093')}${logo}
  <path d="M524 39V106" stroke="#4f5468" stroke-width="2"/>
  ${px('STYLES : 153',560,42,2,'#bfe991')}${px('FAMILIES : 13',560,66,2,'#76e3df')}${px('LICENCE : MIT',560,90,2,'#e6fc66')}
  ${px('FILE AREA / PUBLIC ACCESS',54,140,2,'#e4e8ee')}${px('04 ENTRIES',768,140,2,'#e179c4')}
  <path d="M43 168H907M43 329H907" stroke="#6b748b" stroke-width="2"/>
  ${table}
  <rect x="54" y="344" width="22" height="20" fill="#76e3df"/>${px('S',61,347,2,'#0a0c11')}${px('STYLES',88,347,2,'#bcc6ce')}
  <rect x="239" y="344" width="22" height="20" fill="#bfe991"/>${px('E',246,347,2,'#0a0c11')}${px('EXAMPLES',273,347,2,'#bcc6ce')}
  <rect x="470" y="344" width="22" height="20" fill="#e6fc66"/>${px('T',477,347,2,'#0a0c11')}${px('TOOLS',504,347,2,'#bcc6ce')}
  <rect x="658" y="344" width="22" height="20" fill="#e179c4"/>${px('Q',665,347,2,'#0a0c11')}${px('QUIT',692,347,2,'#bcc6ce')}
  ${px('README.NFO > SELECT A FILE AREA',54,374,1,'#76e3df')}<rect x="244" y="374" width="5" height="7" fill="#76e3df"/>
  <rect x="891" y="36" width="17" height="17" fill="#e179c4"/><path d="M895 40h9v9h-9z" fill="#10151e"/>
 </g>`});
const widths=[4,13,7,41];
const border=`+${'-'.repeat(68)}+`;
const tableRule=`+${widths.map(w=>'-'.repeat(w)).join('+')}+`;
const textRow=values=>'|'+values.map((value,i)=>` ${value}`.padEnd(widths[i])).join('|')+'|';
const descriptions=['Researched retro style catalogue','Text and SVG visual families','Local previews and validation','Copy, customise and share'];
const text=[border,
  '| README.NFO       STYLES: 153   FAMILIES: 13   LICENCE: MIT'.padEnd(69)+'|',
  tableRule,...rows.map((row,i)=>textRow([...row.slice(0,3),descriptions[i]])),tableRule,
  '| [S] styles   [E] examples   [T] tools'.padEnd(69)+'|',border].join('\n');
const markdown=`<p align="center"><img src="assets/10-ansi-05.svg" width="100%" alt="README.NFO bulletin-board file directory with stats, rows and coloured hotkeys"></p>\n\n\`\`\`text\n${text}\n\`\`\`\n\n[S: Styles](../../styles/INDEX.md) · [E: Examples](../README.md) · [T: Tools](../../tools/preview.mjs) · [MIT licence](../../LICENSE)`;
writeHeader(10,{image,markdown,summary:'BBS data screen with a stats masthead, directory table and inverse-video hotkeys.'});

ansi-07.source:
#!/usr/bin/env node
// RIPscrip vector BBS screen: README header generator for CASTAWAY.
//
//   node examples/castaway/src/51-ripscrip-screen_opus_5.5.mjs
//
// Writes examples/castaway/assets/51-ripscrip-screen_opus_5.5.svg.
// Plain Node, no dependencies, no clock, no Math.random: the same bytes on
// every run. (The .md beside the assets is hand-written, not generated.)
//
// The style (catalogue entry ansi-07) is the RIPscrip BBS screen of 1993-98:
// a 640x350 EGA picture sent as a list of drawing commands, so the caller
// watched it build itself over the modem, primitive by primitive: outlines
// first, then flood fills popping in one region at a time, then text, then the
// clickable buttons. Sixteen fixed colours, 8x8 fill patterns doing the
// in-between tones, thick black outlines, stroke fonts with visibly straight
// segments (a gothic for headings, a serif and a sans for labels), a menu on a
// parchment scroll in the middle of a painted scene, and a bevelled grey
// button at the lower right. Nothing here is copied from any real RIP screen,
// terminal program, icon set or font: every shape and glyph is drawn below.
//
// What changes for Castaway:
//   * the concentric dithered rings behind the title are the daytime sky, a
//     sun-glare that steps from white to deep blue in EGA checker patterns;
//   * the parchment is a door-game menu of her actual activities, with the
//     lightbar parked on "Wait" for most of the minute;
//   * the board is ISLE WAIT BBS (sysop SEA LEVEL); the art is signed by
//     DITHER DINGHY of FLOODFILL ATOLL. All of these are invented.
//
// The loop is 60 s, one pass of the theme: 20 bars of 3 s at 80 BPM. Every
// event starts on a beat (0.75 s) and the big ones on a bar line.
//    0 s   the finished screen: the frame a visitor sees first, and the
//          reduced-motion frame. She nods on every beat.
//    6 s   a bottle draws itself in the sea and hops ashore, one hop a beat
//   12 s   she throws it back; it splashes, turns round, and is at her feet
//          again by 18 s ("returned to sender")
//   21 s   a shark fin in cream headphones draws itself and nods along with
//          her, beat for beat, until 30 s, when it sinks in three steps
//   30 s   the mouse pointer drifts to "(L) Leave (any time)", thinks about
//          it, and goes to the CONTINUE button instead
//   36 s   click (twelve bars in). One beat later the screen clears and the board
//          sends the next screen at 2400 bps: the sky rings, the title, the
//          sea, the island, the palm, the raft, her, the scroll, its text,
//          and last of all the button. The next screen is the same island.
//          It is finished by 54 s and holds until the loop comes round.
//   all the while: clouds, a sailboat and two gulls drift a step at a time
//          until the click; the redraw puts them back, so there is no seam
//
// How it is built: a 640x366 viewBox (350 EGA rows plus a 16-row terminal
// status bar) shown 1.5x taller than wide, so the pixels are tall like EGA's
// on a 4:3 tube and every fill pattern lands on whole device pixels at
// width 640 on a 2x screen. Outlines that trace themselves are paths with
// pathLength=1 and an animated dash offset; fills pop with stepped opacity.
// Each primitive's visibility is "drawn, cleared at 36.75 s, drawn again at
// its own command time", one tiny keyframe rule per distinct command time.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const SLUG = '51-ripscrip-screen_opus_5.5';
const OUT = path.resolve(here, `../assets/${SLUG}.svg`);

// ------------------------------------------------------------------ facts
// Checked 2026-10-02 against D:/python/castaway (read-only): 94 activities in
// activities.toml and growing (81 on four timers, 13 chained); starts snap to
// 3 s bars; theme is a seamless 60 s loop at 80 BPM; every sound comes from
// tools/make_audio.py (181 files in media/audio/audio_catalog.json).
// The image only shows activities that exist: bottle (she throws it out, it
// washes straight back),
// shark_nod (surfaces in headphones and nods to the beat), coconut, fishing,
// the signal hunt up the palm, the sandcastle and the tide, waving for rescue,
// and "she could leave any time".

// ------------------------------------------------------------------ canvas
const W = 640;
const SH = 350; // the EGA screen
const BH = 16; // the terminal's status bar under it
const H = SH + BH;
const ASPECT = 1.5; // each logical row is shown 1.5x taller than wide
const LOOP = 60;
const BEAT = 0.75;
const CLICK = 36; // twelve bars in: the pointer clicks CONTINUE
const CLEAR = CLICK + BEAT; // one beat later the screen clears for the redraw
const SINK = 30; // ten bars in: the shark goes

const E = {
