// Intervals [[a,b],...] inside [0,T) -> a step-end opacity track.
const inside = (iv, t) => iv.some(([a, b]) => t >= a - 1e-9 && t < b - 1e-9);
function opacityKF(name, iv, period = T) {
  const pts = [...new Set([0, ...iv.flat().filter((t) => t > 0 && t < period)])].sort((a, b) => a - b);
