// An original face in the spirit of the PC's 8x8 text font: 2-dot stems, capitals 7 rows tall.
// Each glyph is 8 rows of 7 dots (dot 8 and the 9th column stay dark).
const FONT = new Map();
const G = (ch, rows) => FONT.set(ch, rows.split(' '));
G('A', '.#####. ##...## ##...## ####### ##...## ##...## ##...## .......');
G('B', '######. ##...## ##...## ######. ##...## ##...## ######. .......');
