G('I', '.####.. ..##... ..##... ..##... ..##... ..##... .####.. .......');
G('J', '...#### .....## .....## .....## ##...## ##...## .#####. .......');
G('K', '##...## ##..##. ##.##.. ####... ##.##.. ##..##. ##...## .......');
G('L', '##..... ##..... ##..... ##..... ##..... ##..... ####### .......');
G('M', '##...## ###.### ####### ##.#.## ##...## ##...## ##...## .......');
G('N', '##...## ###..## ####.## ##.#### ##..### ##...## ##...## .......');
G('O', '.#####. ##...## ##...## ##...## ##...## ##...## .#####. .......');
G('P', '######. ##...## ##...## ######. ##..... ##..... ##..... .......');
G('Q', '.#####. ##...## ##...## ##...## ##.#.## ##..##. .###.## .......');
G('R', '######. ##...## ##...## ######. ##.##.. ##..##. ##...## .......');
G('S', '.#####. ##...## ##..... .#####. .....## ##...## .#####. .......');
G('T', '######. ..##... ..##... ..##... ..##... ..##... ..##... .......');
G('U', '##...## ##...## ##...## ##...## ##...## ##...## .#####. .......');
