const OUT = arg('out') ? path.resolve(arg('out')) : path.resolve(here, `../assets/${SLUG}.svg`);
const SHEET = arg('sheet') ? path.resolve(arg('sheet')) : null;
// --view=x,y,w,h and --scale=k: crop and enlarge, for close inspection only (with --out).
const VIEW = arg('view') ? arg('view').split(',').map(Number) : null;
const SCALE = Number(arg('scale') || 2);

// ------------------------------------------------------------------ screen
const SW = 352; // wide playfield, hi-res pixels
const SH = 192; // scanlines
const BX = 8;
const BY = 8;
const VW = SW + 2 * BX;
const VH = SH + 2 * BY;
const BEAT = 0.75; // 80 BPM
const BAR = 4 * BEAT; // 3 s, one bar of the theme

const n = (v, d = 3) => String(+(+v).toFixed(d));
const dly = (s) => `${n(s - T0, 4)}s`;
const mod = (a, m) => ((a % m) + m) % m;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

// A seeded integer hash, for textures (sea crests, sand speckle, bushes).
const hash2 = (x, y, s = 0) => {
  let h = (x * 374761393 + y * 668265263 + s * 2147483647) >>> 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) >>> 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
};

// ------------------------------------------------------------------ palette
// 16 hues x 16 luminances. Hue 0 is the grey ramp; hues 1-15 step 24 degrees
// round the OKLCH wheel from amber, through red, violet, blue, cyan and green,
// back to yellow, which is the order the real chip's hues run in.
function oklchHex(L, C, hDeg) {
  const toRgb = (c) => {
    const h = (hDeg * Math.PI) / 180;
    const a = c * Math.cos(h);
    const b = c * Math.sin(h);
    const l_ = L + 0.3963377774 * a + 0.2158037573 * b;
    const m_ = L - 0.1055613458 * a - 0.0638541728 * b;
    const s_ = L - 0.0894841775 * a - 1.291485548 * b;
    const l = l_ ** 3;
    const m = m_ ** 3;
    const s = s_ ** 3;
