// RFC / man page header for the Castaway README (catalogue style hack-03: "Standards plain text").
// Plain Node, no dependencies, deterministic. Run:
//   node examples/castaway/src/06-rfc-manpage_opus_5.5.mjs
// It rewrites examples/castaway/06-rfc-manpage_opus_5.5.md. Edit this file, not that one.
//
// The style: the two canonical plain-text documents of internet and Unix culture. An RFC in the
// paginated format of RFC 2223 (72 columns, 58 lines a page, two-column first-page header,
// centred title, 3-space body indent, running header and "[Page N]" footer on every page), and
// a section 1 manual page (NAME, SYNOPSIS, DESCRIPTION, OPTIONS... 7-space indent, title and
// footer lines). Only the layouts are reused. The series ("Request for Calm"), the working group
// and the organisation are invented, the memo number is the project's default seed, and nothing
// here claims to be a real RFC or any standards body's work.
//
// Nothing is laid out by hand that a machine could get wrong:
//   * The body is typeset by this file: hard-wrapped at 72 columns with two spaces after a full
//     stop, paginated at 58 lines with keep-together figures, headings kept with their text and
//     no one-line widows or orphans.
//   * The Table of Contents on page 1 is filled in from where each heading actually landed.
//   * Figure 1 (the duty cycle) is drawn from the first half hour of the default run, seed 1992,
//     as printed by `python -B tools/schedule.py` on 2026-10-01. The ship in Figure 4 is the same
//     run. Every other number is from activities.toml, MUSING.md or the tools, checked that day.
// The build refuses to write anything if a line is over 72 columns, has trailing spaces or a
// non-ASCII character, if a page runs over 58 lines, or if the prose grows an em dash.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const SLUG = '06-rfc-manpage_opus_5.5';
const OUT_MD = path.resolve(HERE, '..', `${SLUG}.md`);

const W = 72; // RFC 2223: at most 72 characters a line
const PAGE = 58; // and 58 lines a page, footer included
const DATE = 'October 2026';
const AUTHOR = 'Luke';
const SERIES = 'Request for Calm';
const NUMBER = 1992; // the default seed in activities.toml
const SHORT_TITLE = 'Castaway';
const CATEGORY = 'Informational';

// ------------------------------------------------------------------ counts that drift
// Checked read-only against D:/python/castaway on 2026-10-01 at about 13:15, after activities.toml
// grew from 81 to 92 activities and media/audio from 129 to 151 files. Other sessions keep adding
// to both, so the prose says "at the time of writing". Re-check before this becomes the README:
//   python -B -c "import tomllib,collections as c;d=tomllib.load(open('activities.toml','rb'));
//     a=d['activities'];print(len(a),c.Counter(v['tier'] for v in a.values()),len(d['state']))"
//   python -B tools/schedule.py --json <somewhere outside the project>/run.json   (seed 1992)
const ACTIVITY_COUNT = 92;
const TIER_COUNTS = { regular: 9, occasional: 35, rare: 31, super_rare: 6, chained: 11 };
// how many of each tier came round in the default run (seed 1992, 10:00:00)
const DEFAULT_RUN = { regular: 159, occasional: 32, rare: 13, super_rare: 1, chained: 14 };
const BUSY_PERCENT = 28; // "She is busy 28% of the run" in the same run
const SOUND_FILES = 151; // media/audio/audio_catalog.json, and the last count in MUSING.md
const WORLD_FLAGS = 11; // [state] in activities.toml; the record format below gives them 16 bits
if (Object.values(TIER_COUNTS).reduce((t, n) => t + n, 0) !== ACTIVITY_COUNT) throw new Error('tier counts do not add up');
if (WORLD_FLAGS > 16) throw new Error('the record format has run out of flag bits');

// ------------------------------------------------------------------ inline markup
// Text is built as plain strings. Bold, italic and links are zero-width marker characters, so
// widths can be measured exactly; HTML is produced at the very end.
const links = [];
const B = (s) => `\u0001${s}\u0002`;
const I = (s) => `\u0005${s}\u0006`;
const A = (s, href) => {
  links.push(href);
  return `\u0003${String.fromCharCode(0xe000 + links.length - 1)}${s}\u0004`;
};
const visible = (s) => s.replace(/\u0003[-]/g, '').replace(/[\u0001\u0002\u0004\u0005\u0006]/g, '');
const len = (s) => [...visible(s)].length;
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const toHtml = (s) =>
  esc(s)
    .replace(/\u0001/g, '<b>')
    .replace(/\u0002/g, '</b>')
    .replace(/\u0005/g, '<i>')
    .replace(/\u0006/g, '</i>')
    .replace(/\u0003([-])/g, (_, c) => `<a href="${esc(links[c.charCodeAt(0) - 0xe000])}">`)
    .replace(/\u0004/g, '</a>');

// The files a README at the project root can link to.
const FILES = {
  activities: 'activities.toml',
  musing: 'MUSING.md',
  serve: 'tools/serve.py',
  schedule: 'tools/schedule.py',
  audio: 'tools/make_audio.py',
  demo: 'tools/render_demo.py',
  web: 'web/index.html',
};
const LOCAL = 'http://127.0.0.1:8765/';
const file = (k) => A(FILES[k], FILES[k]);
const cite = (tag, k) => A(`[${tag}]`, FILES[k]);
const local = () => A(LOCAL, LOCAL);

// ------------------------------------------------------------------ typesetting
// Two spaces after a full stop, as the RFC Editor's typewriter intended.
const twoSpace = (s) => s.replace(/([.?!][")\]\u0002\u0004]?) (?=[A-Z0-9"(\[\u0001\u0003])/g, '$1  ');

// Cross-references and dates never break across a line ("Figure / 1" is how memos get lost).
// A lone "a" or "A" never ends a line either.
const glue = (s) =>
  s.replace(/(^| )([Aa]) (?=[a-z0-9])/g, '$1$2 ').replace(/\b(Figure|Section|Table) (\d)/g, '$1 $2').replace(/\b(\d+) (October) (\d{4})/g, '$1 $2 $3');

function wrap(text, indent = 3, hang = indent, width = W) {
  const parts = glue(twoSpace(text)).split(/( +)/);
  const out = [];
  let cur = '';
  let curLen = 0;
  let sep = '';
  for (let i = 0; i < parts.length; i++) {
    const p = parts[i];
    if (i % 2 === 1) {
      sep = p;
      continue;
    }
    if (p === '') continue;
    const wl = len(p);
    if (curLen === 0) {
      const ind = out.length === 0 ? indent : hang;
      cur = ' '.repeat(ind) + p;
      curLen = ind + wl;
    } else if (curLen + sep.length + wl <= width) {
      cur += sep + p;
      curLen += sep.length + wl;
    } else {
      out.push(cur);
      cur = ' '.repeat(hang) + p;
      curLen = hang + wl;
    }
  }
  if (curLen) out.push(cur);
  return out.map((l) => l.replace(/ /g, ' ')); // a no-break space only holds words together
}
const nb = (s) => s.replace(/ /g, ' ');

const center = (s, width = W) => ' '.repeat(Math.max(0, Math.floor((width - len(s)) / 2))) + s;
const padTo = (s, n) => s + ' '.repeat(Math.max(0, n - len(s)));
function threePart(l, c, r, width = W) {
  const cs = Math.floor((width - len(c)) / 2);
  const left = padTo(l, cs) + c;
  const out = padTo(left, width - len(r)) + r;
  if (len(l) >= cs || len(left) > width - len(r)) throw new Error(`three-part line collides: ${visible(out)}`);
  return out;
}
const twoCol = (l, r, width = W) => (r ? padTo(l, width - len(r)) + r : l);

// ------------------------------------------------------------------ blocks
// h: section heading (kept with what follows); p: paragraph (may split across pages, never
// leaving a single line behind); fig: figure or table (kept together); dl: definition with a
// hanging indent; li: "o" bullet; raw: lines as given.
const h = (num, title, opts = {}) => ({ t: 'h', num, title, ...opts });
const p = (text) => ({ t: 'p', text });
const dl = (term, text) => ({ t: 'p', text: `${term}  ${text}`, hang: 6 });
const li = (text) => ({ t: 'p', text: `o  ${text}`, hang: 6 });
const fig = (lines, caption) => ({ t: 'fig', lines, caption });
const notes = (items) => ({ t: 'pl', lines: items.flatMap(([n, text]) => wrap(`(${n})  ${text}`, 3, 8)) });

function render(b) {
  if (b.t === 'h') return [B(b.num ? `${b.num}  ${b.title}` : b.title)];
  if (b.t === 'p') return wrap(b.text, 3, b.hang ?? 3);
  if (b.t === 'pl') return b.lines;
  if (b.t === 'fig') return b.caption ? [...b.lines, '', center(b.caption)] : b.lines;
  throw new Error(`unknown block ${b.t}`);
}

// ------------------------------------------------------------------ figures

// Figure 1: the first half hour of the default run, seed 1992, as printed by
// `python -B tools/schedule.py` on 2026-10-01 ("FIRST 0:30:00"). Start and length in seconds.
// Her lane is drawn anonymously; only the activities this header talks about are named in it.
const FIRST_HALF_HOUR = {
  castaway: [
    [12, 49], [249, 93], [456, 42], [624, 31], [834, 33], [957, 41],
    [1179, 33], // stroll
    [1449, 51], // coconut_sip, 0:24:09
    [1689, 22], // jog_lap
  ],
  sea_sky: [[1458, 148]], // ship_passes_unseen, 0:24:18 to 0:26:46
};
const CELL = 30; // seconds a column
const COLS = 1800 / CELL;
function lane

hack-04.source:
// PGP clearsigned message header for the Castaway README (style catalogue entry hack-04:
// "PGP clearsigned message block (cypherpunk list post)").
// Plain Node, no dependencies, deterministic. Run:
//   node examples/castaway/src/76-clearsigned-message_opus_5.5.mjs
// It rewrites examples/castaway/76-clearsigned-message_opus_5.5.md. Edit this file, not that one.
//
// THE STYLE
// The cleartext signature framework of OpenPGP (RFC 4880, section 7): a "-----BEGIN PGP SIGNED
// MESSAGE-----" line, a "Hash:" armor header, exactly one blank line, the text itself with every
// line that starts with a hyphen dash-escaped as "- -", then an ASCII-armoured signature block:
// a Version: header (the 1990s tell; this one names no program, because none made it), Comment:
// headers, a blank line, a rectangle of base64 64 characters wide, a short last line, the "="
// CRC-24 checksum line and the END delimiter. The zine-footer variant (a "PUBLIC KEY BLOCK", a
// taller base64 rectangle) closes the README in a <details> block. The letter closes the way a
// 1990s list manifesto does: a name, an e-mail address and a date on three lines (the address is
// on .invalid, which is reserved and never resolves, so mail to it bounces, like the bottle).
// The delimiter format is an open standard; nothing is copied from any real post, key or
// signature.
//
// NOTHING HERE IS FAKE
// The catalogue's caveat is that a made-up signature block misleads people into trusting it, so
// this one is real: every byte of the armour is built here, from scratch, as OpenPGP v4 packets
// (an Ed25519 key, algorithm 22; a canonical-text signature, type 0x01, over SHA-256), and the
// message verifies with stock GnuPG (checked with GnuPG 2.4.9 on 2026-10-01 and again, after the
// review changes, on 2026-10-02):
//   gpg --import README.md
//   sed -n '/^-----BEGIN PGP SIGNED/,/^-----END/p' README.md | gpg --verify
// (Plain `gpg --verify README.md` says Good signature too, then trips over the key block.)
// The key, though, is a DEMO key, and says so in its own user ID: its secret half is the SHA-256
// of the sentence in KEY_PHRASE below (printed in the README too), so anyone can sign as "Palm
// Notary". The signature therefore proves only that not one byte of
// the text has changed, and nothing about who wrote it. The README says exactly that.
// To sign the same letter with a real key instead (no logo, then: gpg cannot do that part):
//   node examples/castaway/src/76-clearsigned-message_opus_5.5.mjs --body | gpg --clearsign
//
// THE PICTURES INSIDE THE BASE64
// Base64 is an alphabet of letters, digits, "+" and "/", and four characters always encode three
// bytes. So any 64-character line made of that alphabet is the encoding of some 48 bytes. The
// generator draws a picture out of base64 characters (the CASTAWAY logo for the signature, the
// palm's portrait for the key), decodes it to bytes, and stores those bytes in a notation
// subpacket (type 20) in the HASHED area of the signature, padded so the bytes land on a line
// boundary of the armour. When the packet is armoured again, the picture comes back out, line
// for line, inside a real, verifying signature. The pictures are signed too: change one "M" in
// the logo and the block stops verifying (the armour's CRC-24 notices first; fix that up and
// the signature fails instead).
//
// Everything is new and invented: the Palm Notary (the demo key's name), the domain
// bottle.invalid (for the notations and the castaway's address; .invalid is reserved and never
// resolves), the letter, the logo font and the palm. Castaway is Luke's own project; the jokes
// are about it and nothing else.
// The notation name must stay at most 22 characters ("logo@" + domain) or the logo slips down
// an armour line and a row of filler base64 appears above it.
//
// The build refuses to write anything if a body line is over 70 columns, has trailing spaces or
// a character outside printable 7-bit ASCII, if any armour line is not where the picture put it,
// or if the signature does not verify under Node's own Ed25519 check.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const SLUG = '76-clearsigned-message_opus_5.5';
const OUT = path.resolve(HERE, '..', `${SLUG}.md`);

// ---------------------------------------------------------------------------------------------
// 0. Fixed inputs. Same inputs, same bytes, every run.
// ---------------------------------------------------------------------------------------------
const KEY_PHRASE = 'Castaway demo key. The palm notary signs anything. Seed 1992. Trust nobody.';
const USER_ID = 'Palm Notary (demo key)';
const NOTATION_DOMAIN = 'bottle.invalid';
// The armour's Version: header. In the 1990s it named the program; no program made this one.
const VERSION = 'hand-rolled in plain Node (no gpg, no npm)';
const KEY_TIME = Date.UTC(2026, 9, 1, 0, 0, 0) / 1000; // 1 Oct 2026, 00:00:00 UTC
const SIG_TIME = Date.UTC(2026, 9, 1, 10, 0, 0) / 1000; // 1 Oct 2026, 10:00:00 UTC (a Thursday)
const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const LINE = 64; // base64 characters per armour line (GnuPG's width; the spec allows 76)
const LINE_BYTES = (LINE / 4) * 3; // 48 bytes per armour line

// ---------------------------------------------------------------------------------------------
// 1. Byte helpers and OpenPGP framing
// ---------------------------------------------------------------------------------------------
const sha256 = (...parts) => crypto.createHash('sha256').update(Buffer.concat(parts)).digest();
const sha1 = (...parts) => crypto.createHash('sha1').update(Buffer.concat(parts)).digest();
const u8 = (...n) => Buffer.from(n);
const u16 = (n) => u8((n >> 8) & 255, n & 255);
const u32 = (n) => u8((n >>> 24) & 255, (n >>> 16) & 255, (n >>> 8) & 255, n & 255);

// A deterministic byte stream (SHA-256 in counter mode) for the filler around the pictures.
function byteStream(label) {
  let counter = 0;
  let pool = Buffer.alloc(0);
  return (n) => {
    while (pool.length < n) pool = Buffer.concat([pool, sha256(Buffer.from(`${label}#${counter++}`))]);
    const out = pool.subarray(0, n);
    pool = pool.subarray(n);
    return Buffer.from(out);
  };
}

// RFC 4880 4.2.2 new-format lengths (also used, minus the tag, for subpacket lengths).
function lengthOctets(len) {
  if (len < 192) return u8(len);
  if (len < 8384) return u8(((len - 192) >> 8) + 192, (len - 192) & 255);
  return Buffer.concat([u8(255), u32(len)]);
}
const packet = (tag, body) => Buffer.concat([u8(0xc0 | tag), lengthOctets(body.length), body]);
const subpacket = (type, data) => Buffer.concat([lengthOctets(data.length + 1), u8(type), data]);

// Multiprecision integer: bit count, then the big-endian bytes without leading zeros.
function mpi(bytes) {
  let i = 0;
  while (i < bytes.length - 1 && bytes[i] === 0) i++;
  const b = bytes.subarray(i);
  const bits = (b.length - 1) * 8 + (b[0] === 0 ? 0 : 32 - Math.clz32(b[0]));
  return Buffer.concat([u16(bits), b]);
}

// Notation data (5.2.3.16): 4 flag octets (all zero: not human-readable), name and value lengths.
const notation = (name, value) =>
  subpacket(20, Buffer.concat([u8(0, 0, 0, 0), u16(name.length), u16(value.length), Buffer.from(name), value]));

// ASCII armour body: base64 at 64 a line, then "=" and the base64 of the CRC-24.
function crc24(bytes) {
  let crc = 0xb704ce;
  for (const b of bytes) {
    crc ^= b << 16;
    for (let i = 0; i < 8; i++) {
      crc <<= 1;
      if (crc & 0x1000000) crc ^= 0x1864cfb;
    }
  }
  return crc & 0xffffff;
}
function armour(bytes) {
  const b64 = bytes.toString('base64');
  const rows = [];
  for (let i = 0; i < b64.length; i += LINE) rows.push(b64.slice(i, i + LINE));
  const c = crc24(bytes);
  rows.push('=' + u8((c >> 16) & 255, (c >> 8) & 255, c & 255).toString('base64'));
  return rows;
}

// ---------------------------------------------------------------------------------------------
// 2. The demo key: Ed25519 from a public sentence (so: not a secret, by design)
// ---------------------------------------------------------------------------------------------
const seed = sha256(Buffer.from(KEY_PHRASE));
const privateKey = crypto.createPrivateKey({
  key: Buffer.concat([Buffer.from('302e020100300506032b657004220420', 'hex'), seed]),
  format: 'der',
  type: 'pkcs8',
});
const publicKey = crypto.createPublicKey(privateKey);
const rawPublic = Buffer.from(publicKey.export({ format: 'jwk' }).x, 'base64url');
const ED25519_OID = Buffer.from('2b06010401da470f01', 'hex'); // 1.3.6.1.4.1.11591.15.1
const keyBody = Buffer.concat([
  u8(4), u32(KEY_TIME), u8(22), u8(ED25519_OID.length), ED25519_OID, mpi(Buffer.concat([u8(0x40), rawPublic])),
]);
const keyHashPrefix = Buffer.concat([u8(0x99), u16(keyBody.length), keyBody]);
const fingerprint = sha

