G('I', '.###. ..#.. ..#.. ..#.. ..#.. ..#.. .###.');
G('J', '..### ...#. ...#. ...#. ...#. #..#. .##..');
G('K', '#...# #..#. #.#.. ##... #.#.. #..#. #...#');
