G('O', '.###. #...# #...# #...# #...# #...# .###.');
G('P', '####. #...# #...# ####. #.... #.... #....');
G('Q', '.###. #...# #...# #...# #.#.# #..#. .##.#');
G('R', '####. #...# #...# ####. #.#.. #..#. #...#');
