G('V', '#...# #...# #...# #...# #...# .#.#. ..#..');
G('W', '#...# #...# #...# #.#.# #.#.# #.#.# .#.#.');
G('X', '#...# #...# .#.#. ..#.. .#.#. #...# #...#');
