#!/usr/bin/env node
// PC diskmag reader: README header generator for CASTAWAY.
//
//   node examples/castaway/src/83-diskmag-reader_opus_5.5.mjs
//
// Writes examples/castaway/assets/83-diskmag-reader_opus_5.5.svg.
// Plain Node, no dependencies, no clock, no Math.random: the same bytes on
// every run. (The .md beside the assets is hand-written, not generated.)
//
// The style (catalogue entry hack-12) is the reader screen of a 1990s PC
// diskmag, a magazine shipped as a program: 640x480 in 16 colours, split into
// three bands. A painted logo with an issue number across the top, with a row
// of utility buttons; a reading area in the middle where the main menu and
// then each article, set in two columns of a custom proportional pixel font,
// slide past sideways; a strip of painted artwork along the bottom; and between
// them a status box with the author, the article title and a small flag, a
// one-tune module player with a level meter, and the page counter. A mouse
// pointer does the reading.
//
// Nothing is copied: the magazine is this project's own (issue #00), the
// staff (MARRAM, LUGWORM, CUTTLEBONE, BLADDERWRACK) and the publisher (GALLEY
// PROOF) are invented, and the logo letters, both fonts, the raft-log frame,
// the flag and the island strip are all drawn here from scratch.
//
// The party report on page 2 is real data: the default run (10:00:00, seed
// 1992) as `python tools/schedule.py` simulated it on 2026-10-01. The schedule
// changes as activities are added, so the report is dated, like any issue.
//
// Timing. One loop is 60 s, the length of the theme (20 bars of 3 s):
//   pages    five pages, 12 s (4 bars) each; each turn is a one-beat (0.75 s)
//            sideways scroll, and the last turn scrolls onto a copy of page 1,
//            so the wrap is invisible
//   pointer  wanders to something worth reading, then clicks the next page
//   player   the tune clock counts 0:00 to 0:59 and wraps with the loop; the
//            level meter steps on half beats
//   strip    her head dips on every beat, the shore foam and sea glints swap
//            on the beat, clouds drift a pixel at a time, and a coconut on
//            crab legs takes a stroll
// The first frame (and the reduced-motion frame) is page 1: logo, contents,
// editorial and the island, all readable.
//
// How it is drawn (no <text>, no filters): pixels are merged into runs, one
// <path> per colour; dithered gradient rows are a flat rect plus a 1 px line
// whose dash pattern is that row of a 4x4 Bayer matrix; text is <use>
// references to one path per glyph.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const SLUG = '83-diskmag-reader_opus_5.5';
const OUT = path.resolve(here, `../assets/${SLUG}.svg`);

// ------------------------------------------------------------------ canvas
const W = 640;
const H = 480;
const LOOP = 60; // s: one pass of the theme
const BEAT = 0.75; // 80 BPM
const PAGE_T = 12; // s per page (4 bars)
const SLIDE = 0.75; // s per page turn (1 beat)
const PAGES = 5;

// bands
const TOP_H = 92;
const LOG = 10;
const FR_Y0 = TOP_H; // top log
const FR_Y1 = 360; // bottom of bottom log
const IN_X0 = 12;
const IN_X1 = 628;
const IN_Y0 = FR_Y0 + LOG; // 102
const IN_Y1 = FR_Y1 - LOG; // 350
const PAGE_W = IN_X1 - IN_X0; // 616
const ST_Y0 = FR_Y1; // status bar
const ST_Y1 = 384;
const ART_Y = ST_Y1; // art strip
const ART_H = H - ART_Y; // 96

// ------------------------------------------------------------------ palette
// An original 16-colour ramp: night-navy interface, sunny island.
const C = {
  ink: '#090d1a',
  navy: '#121a33',
  navy2: '#22345e',
  deep: '#2f74c0',
  sea: '#4fb0e8',
  haze: '#a8e6f0',
  paper: '#f6f0e0',
  peach: '#f1cfa0',
  sand: '#d6a35c',
  wood: '#8a5a2e',
  bark: '#4a2c17',
  coral: '#ff8a6b',
  red: '#d24a43',
  sun: '#ffd45e',
  palm: '#6cc04a',
  fern: '#2f7a3e',
};

// ----------------------------------------------------------------- helpers
const n = (v) => (Number.isInteger(v) ? String(v) : String(+v.toFixed(3)));
function mulberry32(a) {
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const makeGrid = (w, h) => Array.from({ length: h }, () => new Array(w).fill(null));

// Lit cells -> compact path: horizontal runs, merged down identical rows.
function runsPath(isOn, w, h, ox = 0, oy = 0) {
  const rects = [];
  let active = new Map();
  for (let y = 0; y < h; y++) {
    const next = new Map();
    let x = 0;
    while (x < w) {
      if (!isOn(x, y)) { x++; continue; }
      let x1 = x;
      while (x1 < w && isOn(x1, y)) x1++;
      const key = `${x},${x1}`;
      const r = active.get(key);
      if (r) { r.h++; next.set(key, r); } else { const nr = { x, y, w: x1 - x, h: 1 }; rects.push(nr); next.set(key, nr); }
      x = x1;
    }
    active = next;
  }
  return rects.map((r) => `M${n(r.x + ox)} ${n(r.y + oy)}h${r.w}v${r.h}h${-r.w}`).join('');
}
// A colour grid (palette keys, null = clear) -> one <path> per colour.
function gridPaths(grid, ox = 0, oy = 0) {
  const h = grid.length;
  const w = grid[0].length;
  const keys = [];
  for (const row of grid) for (const c of row) if (c && !keys.includes(c)) keys.push(c);
  return keys.map((k) => `<path fill="${C[k] ?? k}" d="${runsPath((x, y) => grid[y][x] === k, w, h, ox, oy)}"/>`).join('');
}
// Parse a little picture: rows of characters, each mapped through `key`.
function sprite(rows, key) {
  const w = Math.max(...rows.map((r) => r.length));
  const g = makeGrid(w, rows.length);
  rows.forEach((r, y) => [...r].forEach((ch, x) => { if (key[ch]) g[y][x] = key[ch]; }));
  return g;
}

// ------------------------------------------------------------- dithering
const BAYER = [[0, 8, 2, 10], [12, 4, 14, 6], [3, 11, 1, 9], [15, 7, 13, 5]];
const ditherOn = (x, y, f) => f * 16 > BAYER[y & 3][x & 3];
// One row's 4-px Bayer pattern as dash attributes (lines start at x % 4 == 0).
const dashAttrs = (y, f) => dashBits([0, 1, 2, 3].map((x) => ditherOn(x, y, f)));
function dashBits(bits) {
  if (bits.every(Boolean)) return '';
  if (!bits.some(Boolean)) return null;
  let k = 0;
  while (!(bits[k] && !bits[(k + 3) % 4])) k++;
  const rot = [0, 1, 2, 3].map((i) => bits[(k + i) % 4]);
  const runs = [];
  let cur = rot[0];
  let len = 0;
  for (const b of rot) { if (b === cur) len++; else { runs.push(len); cur = b; len = 1; } }
  runs.push(len);
  return ` stroke-dasharray="${runs.join(' ')}"${k ? ` stroke-dashoffset="${(4 - k) % 4}"` : ''}`;
}
// Row ramp: segments [[rows, fromKey, toKey]] -> [{y, a, b, f}] (f = share of b)
function ramp(y0, segments) {
  const rows = [];
  let y = y0;
  for (const [len, a, b] of segments) {
    for (let i = 0; i < len; i++) {
      const f = a === b ? 0 : Math.round(((i + 0.5) / len) * 16) / 16;
      rows.push({ y: y++, a, b, f });
    }
  }
  return rows;
}
// Dithered horizontal bands over [x0, x1): flat rects plus dashed lines.
function bands(rows, x0, x1) {
  let out = '';
  for (let i = 0; i < rows.length;) {
    let j = i;
    while (j + 1 < rows.length && rows[j + 1].a === rows[i].a && rows[j + 1].y === rows[j].y + 1) j++;
    out += `<rect x="${x0}" y="${rows[i].y}" width="${x1 - x0}" height="${rows[j].y - rows[i].y + 1}" fill="${C[rows[i].a]}"/>`;
    i = j + 1;
  }
  const groups = new Map();
  for (const r of rows) {
    if (r.a === r.b || r.f <= 0) continue;
    const da = dashAttrs(r.y, r.f);
    if (da === null) continue;
    const key = `${r.b}|${da}`;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(r.y);
  }
  const sx = Math.floor(x0 / 4) * 4;
  for (const [key, ys] of groups) {
    const [b, da] = key.split('|');
    out += `<path stroke="${C[b]}"${da} d="${ys.map((y) => `M${sx} ${y + 0.5}h${x1 - sx}`).join('')}"/>`;
  }
  return out;
}
// Colour at a pixel for a ramp row list indexed by y.
function rampAt(rowsByY, x, y) {
  const r = rowsByY.get(y);
  if (!r) return null;
  return r.f > 0 && r.a !== r.b && ditherOn(x, y, r.f) ? r.b : r.a;
}

// ------------------------------------------------------------- the font
// "Galley", the magazine's own proportional face: 2 px stems, 1 px bars,
// 8 px capitals, 6 px x-height, 2 px descenders (rows 0-9; baseline under
// row 7). Each glyph: optional "first row|" then rows split by "/".
const GLYPHS = {
  A: '.####./##..##/##..##/##..##/######/##..##/##..##/##..##',
  B: '#####./##..##/##..##/#####./##..##/##..##/##..##/#####.',
  C: '.####./##..##/##..../##..../##..../##..../##..##/.####.',
  D: '####../##.##./##..##/##..##/##..##/##..##/##.##./####..',
  E: '######/##..../##..../#####./##..../##..../##..../######',
  F: '######/##..../##..../#####./##..../##..../##..../##....',
  G: '.####./##..##/##..../##..../##.###/##..##/##..##/.#####',

hack-13.source:
#!/usr/bin/env node
// CASTAWAY on a war-room big board: the wall of rear-projected vector maps
// in a dark command centre, as in hacker cinema of the early 1980s (the
// style catalogue's entry hack-13). Thin single-stroke coastlines on black,
// tracks that arc from one place to another with a blip where they land,
// big counters that climb, stroke-drawn capitals with wide spacing, every
// element in one flat saturated colour with a soft glow, a separate
// monochrome monitor with a typed dialogue, and a noughts-and-crosses grid
// that plays itself to a draw, over and over.
//
//   node examples/castaway/src/84-war-room-big-board_opus_5.5.mjs
//
// Regenerates ../assets/84-war-room-big-board_opus_5.5.svg. The .md beside
// it is hand-written. Plain Node, no dependencies, deterministic: no clock,
// no Math.random (one seeded PRNG for the counters' event times).
//
// Nothing here is copied from the film, its screens or anyone's data. The
// coastlines were typed in by hand, from memory, a point every few degrees
// (they are as wobbly as that sounds, which suits a 1983 vector board); the
// stroke alphabet, the island chart and every word are made up in this file.
// The board belongs to LOW STAKES COMMAND and its computer is called
// MOLLUSC: both invented, both very calm.
//
// How it works
//   * GLOW. Everything that glows lives once in <g id="ALL"> inside <defs>
//     and is drawn four times with <use>: a wide faint halo, a mid glow, the
//     coloured line itself, and a thin white-hot core. Each <use> passes its
//     stroke-width multiplier and extra width down as CSS custom properties,
//     so the four passes need no copies of the data and no filters.
//   * TIME. One 30 s loop. From 0.5 s to 24.5 s the board replays a typical
//     ten-hour run at 25 simulated minutes per second: the clock climbs to
//     10:00, the bar counter to 12000, the four timers' event counters to the
//     median counts of the schedule (about 155, 30, 13 and 2), tracks arc in
//     across the Pacific and the island chart, and the tickers say what
//     happened. At 25.7 s the screens blank, at 27 s the coastlines redraw
//     stroke by stroke, and the loop comes round on a fully drawn board.
//   * COUNTERS are vertical strips of stroke digits under a clip path, moved
//     with steps(1,end) keyframes. Digits that change faster than a screen
//     can show (minutes, tens and units of bars) are spinners: a short
//     steps(10) loop whose phase matches the real count, so every digit
//     still lands exactly on 10:00 and 12000.
//   * THE DEFAULT STYLE IS THE LAST FRAME: every animated thing's static
//     value is its end-of-run state, so prefers-reduced-motion simply turns
//     animation off and leaves a complete, readable board.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const SLUG = '84-war-room-big-board_opus_5.5';
const OUT = path.join(HERE, '..', 'assets', `${SLUG}.svg`);

// ---------------------------------------------------------------------------
// Frame and timing
// ---------------------------------------------------------------------------
const W = 1280, H = 720;
const T = 30;                 // seconds per loop
const RUN0 = 0.5;             // replay starts
const RATE = 25;              // simulated minutes per real second
const RUN1 = RUN0 + 600 / RATE; // 24.5 s: 10:00:00 reached
const BLANK0 = 25.7, BLANK1 = 26.1, UNBLANK = 27.0; // screens fade out, come back
const RESET = 26.5;           // counters and tracks reset while blank
const tm = (min) => RUN0 + min / RATE; // simulated minute -> loop second

// When things happen in the replayed run, in simulated minutes. The placing
// is made up (the board says so); the totals on screen 3 are the real ones.
// Screen 1 (the island) and screen 2 (the Pacific) share one timeline, and
// the BUSY lamp is built from it, so the ship only ever crosses while she
// is busy fishing.
const ISLE = {
  turtle: 90, sandcastle: 160, tide: 215, hydrofoil: 260, coconut: 330,
  fishing: 400, signal: 490, kumara: 545,
};
const SHIP = 410;             // sets out once she is fishing

// colours: flat and saturated, one per kind of thing
const C = {
  coast: '#3fa9ff',
  grid: '#2f6fa8',
  track: '#ff4b3e',
  yel: '#ffd23f',
  wht: '#f4f8ff',
  dim: '#8fa6bf',
  palm: '#5dff7a',
  coral: '#ff7a5c',
  raft: '#ff9f3f',
  term: '#4dff88',
  cyan: '#5ef0ff',
};

// ---------------------------------------------------------------------------
// Small helpers
// ---------------------------------------------------------------------------
const TAU = Math.PI * 2;
const r1 = (n) => {
  let s = (Math.round(n * 10) / 10).toFixed(1);
  if (s.endsWith('.0')) s = s.slice(0, -2);
  if (s === '-0') s = '0';
  return s.replace(/^(-?)0\./, '$1.');
};
const nums = (arr) => arr.reduce((s, v, i) => s + (i && !v.startsWith('-') ? ' ' : '') + v, '');
const pc = (t) => {
  const v = Math.max(0, Math.min(100, (t / T) * 100));
  return (Math.round(v * 1000) / 1000) + '%';
};
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

// relative path from absolute polylines, rounding done on absolute values
const polyD = (polys) => {
  let out = '';
  for (const p of polys) {
    const r = p.map(([x, y]) => [Math.round(x * 10), Math.round(y * 10)]);
    out += 'M' + nums([r1(r[0][0] / 10), r1(r[0][1] / 10)]);
    if (r.length === 1) { out += 'h0'; continue; }
    const d = [];
    for (let i = 1; i < r.length; i++) d.push(r1((r[i][0] - r[i - 1][0]) / 10), r1((r[i][1] - r[i - 1][1]) / 10));
    out += 'l' + nums(d);
  }
  return out;
};

// seeded PRNG (mulberry32)
const rng = (seed) => () => {
  seed |= 0; seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};

// points on an ellipse arc, degrees, y down (90 = bottom)
const E = (cx, cy, rx, ry, a0, a1, n) => {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const a = ((a0 + ((a1 - a0) * i) / n) * Math.PI) / 180;
    pts.push([cx + rx * Math.cos(a), cy + ry * Math.sin(a)]);
  }
  return pts;
};

// Catmull-Rom through points, sampled
const spline = (pts, per = 6) => {
  const out = [];
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[Math.max(0, i - 1)], p1 = pts[i], p2 = pts[i + 1], p3 = pts[Math.min(pts.length - 1, i + 2)];
    for (let k = 0; k < per; k++) {
      const t = k / per, t2 = t * t, t3 = t2 * t;
      out.push([0, 1].map((j) => 0.5 * (2 * p1[j] + (-p0[j] + p2[j]) * t + (2 * p0[j] - 5 * p1[j] + 4 * p2[j] - p3[j]) * t2 + (-p0[j] + 3 * p1[j] - 3 * p2[j] + p3[j]) * t3)));
    }
  }
  out.push(pts[pts.length - 1]);
  return out;
};

