fs.writeFileSync(path.join(DIR, 'assets/41-hack-19.svg'), image);
fs.writeFileSync(path.join(DIR, '41-hack-19.md'), markdown);
fs.writeFileSync(path.join(DIR, '41-hack-19.txt'), transcript + '\n');
