// ---------------------------------------------------------------------------------------------
// An original 8x8 face: 2-pixel stems, 1-pixel bars, capitals 7 rows tall (rows 0-6), one row
// for descenders. Each glyph is 8 rows of 7 columns; column 7 is the gap.
// ---------------------------------------------------------------------------------------------
const FONT = new Map();
