// ------------------------------------------------------------------ the timeline
const LOOP = 15; // five bars of the theme
const BEAT = 0.75; // 80 BPM
const STILL = 7.6; // the reduced-motion frame
const SPS = 100; // timeline samples per second
const css = [];
let uid = 0;
const decl = (v) => {
  const out = [];
