  let name = seen.get(body);
  if (!name) {
    name = 'k' + (uid++).toString(36);
    seen.set(body, name);
    css.push(`@keyframes ${name}{${body}}.${name}{animation:${name} ${LOOP}s step-end infinite}`);
  }
